private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
        if (i < 0 || i >= bb.limit()) {
            return i;
        }
        int c = bb.get(i) & 0xFF;
        if (c < 0x80) { // 1 byte
            sb.append((char) c);
            return i + 1;
        } else if (c < 0xC0) { // unexpected continuation byte
            return i + 1;
        } else if (c < 0xE0) { // 2 bytes
            if (i + 1 >= bb.limit()) {
                return i;
            }
            int c2 = bb.get(i + 1) & 0xFF;
            if ((c2 & 0xC0) != 0x80) {
                return i + 1;
            }
            sb.append((char) ((c & 0x1F) << 6 | (c2 & 0x3F)));
            return i + 2;
        } else if (c < 0xF0) { // 3 bytes
            if (i + 2 >= bb.limit()) {
                return i;
            }
            int c2 = bb.get(i + 1) & 0xFF;
            int c3 = bb.get(i + 2) & 0xFF;
            if ((c2 & 0xC0) != 0x80 || (c3 & 0xC0) != 0x80) {
                return i + 1;
            }
            sb.append((char) ((c & 0x0F) << 12 | (c2 & 0x3F) << 6 | (c3 & 0x3F)));
            return i + 3;
        } else { // 4 bytes
            if (i + 3 >= bb.limit()) {
                return i;
            }
            int c2 = bb.get(i + 1) & 0xFF;
            int c3 = bb.get(i + 2) & 0xFF;
            int c4 = bb.get(i + 3) & 0xFF;
            if ((c2 & 0xC0) != 0x80 || (c3 & 0xC0) != 0x80 || (c4 & 0xC0) != 0x80) {
                return i + 1;
            }
            sb.append((char) ((c & 0x07) << 18 | (c2 & 0x3F) << 12 | (c3 & 0x3F) << 6 | (c4 & 0x3F)));
            return i + 4;
        }
    }

private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int size = bb.limit() - bb.position();
    int octet = bb.get(i + bb.position()) & 0xFF;

    if (octet < 0x80) { // 1-byte character
        sb.append((char) octet);
        return i + 1;
    } else if (octet < 0xE0) { // 2-byte character
        int macron = octet & 0x1F;
        int charCode = (macron << 6) | (bb.get(i + bb.position() + 1) & 0x3F);
        sb.append((char) charCode);
        return i + 2;
    } else if (octet < 0xF0) { // 3-byte character
        int macron = octet & 0x0F;
        int charCode = (macron << 12) | ((bb.get(i + bb.position() + 1) & 0x3F) << 6) | (bb.get(i + bb.position() + 2) & 0x3F);
        sb.append((char) charCode);
        return i + 3;
    } else { // 4-byte character
        int macron = octet & 0x07;
        int charCode = (macron << 18) | ((bb.get(i + bb.position() + 1) & 0x3F) << 12) | ((bb.get(i + bb.position() + 2) & 0x3F) << 6) | (bb.get(i + bb.position() + 3) & 0x3F);
        if (charCode >= 0x10000) {
            sb.appendCodePoint(charCode);
        } else {
            sb.append((char) charCode);
        }
        return i + 4;
    }
}

