private int parseEndOfLine(String headerPart, int end) {
    if (headerPart == null || end < 0 || end >= headerPart.length()) {
        throw new IllegalArgumentException("Invalid input: headerPart is null or end index is out of bounds");
    }

    int i = end;
    // Skip until we find '\r'
    while (i < headerPart.length() && headerPart.charAt(i) != '\r') {
        i++;
    }

    if (i >= headerPart.length()) {
        throw new IllegalArgumentException("No end-of-line marker found");
    }

    // Check if the next character after '\r' is '\n'
    if (i + 1 < headerPart.length() && headerPart.charAt(i + 1) == '\n') {
        return i;
    }

    // If no valid '\r\n' sequence found, throw exception
    throw new IllegalArgumentException("Invalid end-of-line sequence");
}

private int parseEndOfLine(String headerPart, int end) {
    int searchFrom = 0;
    int maxIndex = end;
    for (int i = searchFrom; i + 1 < maxIndex; i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
    }
    return maxIndex;
}

private int parseEndOfLine(String headerPart, int end) {
        // Iterate backward from the given end index
        for (int i = end; i >= 0; i--) {
            char c = headerPart.charAt(i);
            // If we find a carriage return '\r' and it's not the first character, check the previous character
            if (c == '\r' && i > 0) {
                // Check if the previous character is '\n'
                char prev = headerPart.charAt(i - 1);
                if (prev == '\n') {
                    // Return the index of '\n' as it's the first char of the \r\n sequence
                    return i - 1;
                }
            }
        }
        // If no end of line sequence is found, return -1 to indicate it wasn't found.
        return -1;
    }

private int parseEndOfLine(String headerPart, int end) {
    int i = end - 1;
    while (i >= 0 && headerPart.charAt(i) != '\n') {
        i--;
    }
    if (i > 0 && headerPart.charAt(i - 1) == '\r') {
        return i - 1;
    }
    return i;
}

private int parseEndOfLine(String headerPart, int end) {
    for (int i = end - 1; i >= 0; i--) {
        if (headerPart.charAt(i) == '\n') {
            if (i > 0 && headerPart.charAt(i - 1) == '\r') {
                return i - 1;
            }
        }
    }
    return -1;
}

