public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph) {
    if (graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }

    Map<V, V> vertexMap = new HashMap<>();
    for (V vertex : graph.nodes()) {
        vertexMap.put(vertex, vertex);
    }

    Map<E, E> edgeMap = new HashMap<>();
    for (E edge : graph.edges()) {
        edgeMap.put(edge, edge);
    }

    return new IsomorphicGraphMapping<V, E>(graph, vertexMap, edgeMap);
}

public static <V,E>IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph){
    HashMap<V,V> mapping = new HashMap<>();
    for (V vertex : graph.vertices().toArray(new V[0])) {
        mapping.put(vertex, vertex);
    }
    return new IsomorphicGraphMapping<>(mapping);
}

