        throw new IllegalArgumentException("graph must not be null");
    }
    final Map<V,V> vertexMap = new HashMap<>();
    for(V vertex : graph.vertices()) {
        vertexMap.put(vertex, vertex);
    }
    final Map<AbstractGraph.Graph<V,E>, IsomorphicGraphMapping.Graph> edgeMap = new HashMap<>();
    for(E edge : graph.edges()) {
        final IsomorphicGraphMapping.Graph graphWrap = new IsomorphicGraphMapping.Graph(graph, edge);
        edgeMap.put(graphWrap, graphWrap);
    }
    return new IsomorphicGraphMapping<>(graph, vertexMap, edgeMap);
