public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    if (target == null || resultMap == null || resultMap.isEmpty()) {
        return;
    }

    Set<String> partA = new LinkedHashSet<>();
    Set<String> partB = new LinkedHashSet<>();

    for (String key : resultMap.keySet()) {
        if (key != null && key.charAt(0) == 'A') {
            partA.add(key);
        } else if (key != null && key.charAt(0) == 'B') {
            partB.add(key);
        }
    }

    if (partA.isEmpty() && partB.isEmpty()) {
        return;
    }

    for (String a : partA) {
        V vertexA = resultMap.get(a);
        for (String b : partB) {
            V vertexB = resultMap.get(b);
            if (vertexA != null && vertexB != null) {
                try {
                    E edge = makeGraphEdge(vertexA, vertexB);
                    target.addEdge(vertexA, vertexB, edge);
                } catch (Exception e) {
                    //
                }
            }
        }
    }

    if (partA.isEmpty()) {
        for (String b : partB) {
            V vertexB = resultMap.get(b);
            if (vertexB != null) {
                target.addVertex(vertexB);
            }
        }
    }

    if (partB.isEmpty()) {
        for (String a : partA) {
            V vertexA = resultMap.get(a);
            if (vertexA != null) {
                target.addVertex(vertexA);
            }
        }
    }
}

@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Extract Y vertices
    List<V> Y = new ArrayList<>();
    for (Entry<String, V> entry : resultMap.entrySet()) {
        target.addVertex(entry.getValue());
        if (entry.getKey().startsWith("Y")) {
            Y.add(entry.getValue());
        }
    }

    // For each X vertex
    for (Entry<String, V> entry : resultMap.entrySet()) {
        if (entry.getKey().startsWith("X")) {
            // Connect every X vertex to every Y vertex
            for (V y : Y) {
                if (!target.hasEdge(entry.getValue(), y)) {
                    target.addEdge(entry.getValue(), y);
                }
            }
        }
    }
}

