    target.clear();
    Map<String, V> leftPartition = createPartition("left");
    Map<String, V> rightPartition = createPartition("right");

    // Retrieve left partition vertices
    List<V> leftVertices = new ArrayList<>();
    for (String key : leftPartition.keySet()) {
        leftVertices.add(leftPartition.get(key));
    }

    // Retrieve right partition vertices
    List<V> rightVertices = new ArrayList<>();
    for (String key : rightPartition.keySet()) {
        rightVertices.add(rightPartition.get(key));
    }

    // Add all vertices to result map
    resultMap.putAll(leftPartition);
    resultMap.putAll(rightPartition);

    // Create complete bipartite connections
    for (V left : leftVertices) {
        for (V right : rightVertices) {
            E edge = target.addEdge(left, right);
            if (edge != null) {
                persistence.addEdge(left, right, edge);
            }
        }
    }
}

