public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    ByteArrayOutputStream byteOut = new ByteArrayOutputStream();
    int size = 0;
    try {
        size = schema.writeTo(message, byteOut, buffer);
        byteOut.flush();
        byte[] bytes = byteOut.toByteArray();
        CodedOutputStream.writeUInt32NoTag(size, out);
        out.write(bytes);
        out.flush();
    } catch (Exception e) {
        throw new IOException(e);
    } finally {
        byteOut.close();
    }
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = message != null ? schema.size(message, buffer) : 0;
    CodedOutputStream cOut = CodedOutputStream.newInstance(out);
    cOut.writeRawVarint32(size);
    if (size > 0) {
        schema.write(message, cOut, buffer);
    }
    cOut.flush();
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int messageSize = schema.getSerializedSize(message);
    ProtobufWriter.writePositiveInt(out, (long) messageSize);
    schema.writeTo(message, out, buffer);
    return messageSize;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = CodedOutputStream.computeRawBytesSize(message, schema, buffer);
    CodedOutputStream var3 = CodedOutputStream.newInstance(out);
    CodedOutputStream.writeRawBytesSize(size, var3);
    var3.writeRawBytes(message, schema, buffer);
    var3.flush();
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = (int) schema.size(message, buffer);
    Varint.writeUInt32(size, out);
    schema.serialize(message, out, buffer);
    return size;
}

