    // Extract year, month, day from the original timeBucket
    int year = (int) (timeBucket / 1000000);
    int month = (int) ((timeBucket % 1000000) / 10000);
    int day = (int) (timeBucket % 10000);

    // Handle invalid date components
    if (month < 1 || month > 12 || day < 1 || day > 31) {
        return timeBucket; // Return original if invalid
    }

    // Determine the number of days in each month for the given year
    int daysInMonth = getDaysInMonth(year, month);

    // If day exceeds the number of days in the month, return the original timeBucket
    if (day > daysInMonth) {
        return timeBucket;
    }

    // Compute the first day of the current step
    int stepStart = ((day - 1) / dayStep) * dayStep + 1;

    // If the computed stepStart exceeds the number of days in the month, set it to the first day of the month
    if (stepStart > daysInMonth) {
        stepStart = 1;
    }

    // Construct the new timeBucket with the same year, month, and the computed stepStart day
    long compressedTimeBucket = year * 1000000L + month * 10000L + stepStart;

    return compressedTimeBucket;
