            session.writeByte((byte) 0xEF);
            session.writeByte((byte) 0xBF);
            session.writeByte((byte) 0xBD);
        } else {
            session.writeByte((byte) (0xE0 | (c >> 12)));
            session.writeByte((byte) (0x80 | ((c >> 6) & 0x3F)));
            session.writeByte((byte) (0x80 | (c & 0x3F)));
        }
    }
    return lb;
}

