public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<PathSegmentImpl>();
    if (u == null) {
        return segments;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    // According to Javadoc: If the path is an absolute path (starts with '/'),
    // the leading '/' is ignored and is NOT considered a delimiter.
    int start = 0;
    if (path.startsWith("/")) {
        // Skip the leading slash; it's not a delimiter.
        start = 1;
    }
    // If the path starts with a slash, we've set start=1. 
    // Now, we need to iterate over the segments. The delimiter is '/'.
    int i = start;
    while (i < path.length()) {
        int slashIndex = path.indexOf('/', i);
        if (slashIndex == -1) {
            // No more slashes; the rest is a segment.
            String segment = path.substring(i);
            segments.add(new PathSegmentImpl(segment, decode));
            break;
        } else {
            if (slashIndex > i) {
                // A segment exists between i and slashIndex.
                String segment = path.substring(i, slashIndex);
                segments.add(new PathSegmentImpl(segment, decode));
            } else {
                // slashIndex == i, meaning there is an empty segment (e.g., "//"), 
                // so we do NOT add a segment for '' in this case? 
                // Based on typical path segment parsing, consecutive slashes might yield empty segments, 
                // or they might be skipped. The instruction says "leading '/' is ignored and is not a delimiter".
                // We will assume standard path splitting where '' segments are allowed. 
                // However, to be correct, check if the spec for this method implies ignoring empty segments.
                // Since no further details, we add the empty segment.
                segments.add(new PathSegmentImpl("", decode));
            }
            i = slashIndex + 1;
        }
    }
    return segments;
}

