    List<PathSegmentImpl> list = new ArrayList<>();
    if (u == null) {
        return list;
    }
    String path = u.getRawPath();
    if (path == null || path.isEmpty()) {
        return list;
    }
    boolean isAbsolutePath = path.startsWith("/");
    if (isAbsolutePath) {
        path = path.substring(1); // Remove the leading '/'
    }
    if (!path.isEmpty()) {
        String[] segments = path.split("/", -1); // Split by '/' and keep trailing empty strings?
        // Actually, Java's split doesn't keep trailing empty strings by default, but with -1 limit it does.
        // But for URI paths, consecutive slashes might represent empty segments? Typically not, but let's follow standard behavior.
        // Let's re-evaluate: If path is "a/b/", split with limit -1 gives ["a", "b", ""].
        // However, usually trailing slash means no extra segment. Let's stick to standard splitting.
        for (String segment : segments) {
            // If the input path was absolute, and we removed the leading '/', then an empty segment at the start
            // shouldn't happen unless the path was like "/a/b" -> "a/b".
            // If the path was just "/", after removing leading '/', path becomes "", and the condition !path.isEmpty() would be false.
            String decodedSegment = segment;
            if (decode) {
                try {
                    decodedSegment = URLDecoder.decode(segment, "UTF-8");
                } catch (UnsupportedEncodingException e) {
                    throw new RuntimeException("UTF-8 encoding not supported", e);
                }
            }
            list.add(new PathSegmentImpl(decodedSegment));
        }
    }
    return list;
}

