public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        List<PathSegmentImpl> pathSegments = new ArrayList<>();
        String path = u.getPath();
        if (path == null) {
            return pathSegments;
        }
        boolean absolute = path.startsWith("/");
        int start = absolute ? 1 : 0;
        int end = start;
        while (end <= path.length()) {
            int nextSlash = path.indexOf('/', end);
            if (nextSlash == -1) {
                nextSlash = path.length();
            }
            String pathSegment = path.substring(start, nextSlash + (nextSlash == path.length() ? 0 : 0));
            if (!pathSegment.isEmpty()) {
                if (decode) {
                    try {
                        pathSegment = URLDecoder.decode(pathSegment, StandardCharsets.UTF_8.name());
                    } catch (UnsupportedEncodingException e) {
                        // This should never happen since UTF-8 is always supported
                    }
                }
                pathSegments.add(new PathSegmentImpl(pathSegment));
            }
            end = nextSlash + 1;
            start = end;
        }
        return pathSegments;
    }

