    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }

    char typeChar = descriptor.charAt(0);
    int count = 1;

    if (typeChar == 'L') {
        int end = descriptor.indexOf(';', 1);
        if (end < 0) {
            end = descriptor.length() - 1;
        }
        count = end + 1;
    } else if (typeChar == 'S' || typeChar == 'D') {
        count = 2;
    } else {
        count = 1;
    }

    for (int i = 0; i < count; i++) {
        outputFrame.pop();
    }
}

private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }

    int typesToPop;
    int typeStartIndex;

    if (descriptor.startsWith("(")) {
        // Method descriptor: pop the argument types (mov2ip already consumed the return descriptor)
        int closeParenIndex = descriptor.indexOf(')');
        typesToPop = parseTypeDescriptor(descriptor, 1, closeParenIndex);
        typeStartIndex = closeParenIndex + 1; // Start parsing return type to validate or continue if needed
    } else {
        // Type descriptor: pop this single type
        typesToPop = 1;
        typeStartIndex = 0;
    }

    int frameSize = outputFrame.size();
    for (int i = 0; i < typesToPop; i++) {
        if (frameSize - 1 < i) {
            throw new IllegalStateException("Output frame stack underflow: attempted to pop more types than available");
        }
        outputFrame.removeLast();
    }
}

private void pop(final String descriptor) {
    if (descriptor == null) {
        return;
    }
    if (descriptor.startsWith("(")) {
        // Method descriptor: pop the argument types
        int argCount = 0;
        int i = 1;
        while (i < descriptor.length()) {
            char c = descriptor.charAt(i);
            if (c == ')') {
                i++;
                break;
            }
            if (c == '[') {
                // array, skip until we hit a non-'['
                i++;
                continue;
            }
            if (c == 'L') {
                // object type
                int end = descriptor.indexOf(';', i);
                if (end == -1) {
                    end = i;
                }
                i = end + 1;
                argCount++;
                continue;
            }
            // primitive type
            i++;
            // L and primitive types all count as one argument
        }
        // pop each argument type
        for (int j = 0; j < argCount; j++) {
            if (!outputFrame.poppedTypes.isEmpty()) {
                outputFrame.poppedTypes.pop();
            }
        }
    } else {
        // Simple type descriptor: pop one type
        // Check if it's an array type
        int i = 0;
        while (i < descriptor.length()) {
            char c = descriptor.charAt(i);
            if (c == '[') {
                i++;
                continue;
            }
            if (c == 'L') {
                int end = descriptor.indexOf(';', i);
                if (end == -1) {
                    end = i;
                }
                i = end + 1;
                break;
            }
            i++;
            break;
        }
        if (!outputFrame.poppedTypes.isEmpty()) {
            outputFrame.poppedTypes.pop();
        }
    }
}

private void pop(final String descriptor) {
    // Parse the descriptor to get the number of argument types
    Type[] argumentTypes = Type.getArgumentTypes(descriptor);
    // Pop the argumentTypes.length number of types from the stack
    for (int i = 0; i < argumentTypes.length; i++) {
        if (stack.isEmpty()) {
            break; // or throw, but the problem says "as many as described", so if not enough, pop what is available
        }
        stack.pop(); // or stack.removeLast()
    }
}

private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }

    // If it's a method descriptor, start with '('
    if (descriptor.charAt(0) == '(') {
        int index = 1;
        while (index < descriptor.length() && descriptor.charAt(index) != ')') {
            push(); // Abstract type push for each argument
            index++;
        }
        // Skip past ')' and the return type
        index++; // skip ')'
        if (index < descriptor.length()) {
            index = skipType(descriptor, index);
        }
    } else {
        // It's a single type descriptor
        push(); // Push abstract type
    }
}

