public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    if (box == null) {
        throw new IllegalArgumentException("box cannot be null");
    }
    float x = box.getX();
    float y = box.getY();
    float width = box.getWidth();
    float height = box.getHeight();

    if (width <= 0) {
        throw new IllegalArgumentException("box width must be positive, got: " + width);
    }

    float halfWidth = width / 2.0f;
    Box2D leftBox = new Box2D(x, y, halfWidth, height);
    Box2D rightBox = new Box2D(x + halfWidth, y, halfWidth, height);

    return Pair.of(leftBox, rightBox);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    if (box == null) {
        throw new IllegalArgumentException("Box cannot be null");
    }
    float width = box.getWidth();
    float height = box.getHeight();
    float depth = box.getDepth();
    if (width <= 0) {
        throw new IllegalArgumentException("Box width must be positive");
    }
    if (height <= 0) {
        throw new IllegalArgumentException("Box height must be positive");
    }
    if (depth <= 0) {
        throw new IllegalArgumentException("Box depth must be positive");
    }
    float halfWidth = width / 2.0f;
    // Create two boxes with half width, same height and depth
    Box2D box1 = new Box2D(halfWidth, height, depth);
    Box2D box2 = new Box2D(halfWidth, height, depth);
    // Apply same transformation as original box to both
    box1.translate(box.getOrigin().x + halfWidth, box.getOrigin().y, box.getOrigin().z);
    box2.translate(box.getOrigin().x + width, box.getOrigin().y, box.getOrigin().z);
    // For a 2D box, depth may not be used, but we keep for consistency
    return new Pair<Box2D, Box2D>(box1, box2);
}

public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    double midX = (box.left + box.right) / 2.0;
    Box2D leftBox = new Box2D(box.left, box.bottom, midX, box.top);
    Box2D rightBox = new Box2D(midX, box.bottom, box.right, box.top);
    return new Pair<>(leftBox, rightBox);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    if (box == null) {
        throw new IllegalArgumentException("Box cannot be null");
    }

    float xMid = (box.x + box.x + box.width) / 2.0f;

    Box2D leftBox = new Box2D(box.x, box.y, xMid - box.x, box.height);
    Box2D rightBox = new Box2D(xMid, box.y, box.x + box.width - xMid, box.height);

    return new Pair<>(leftBox, rightBox);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    if (box == null) {
        throw new IllegalArgumentException("Box cannot be null");
    }

    double left = box.getLeft();
    double right = box.getRight();
    double bottom = box.getBottom();
    double top = box.getTop();

    double midX = (left + right) / 2.0;

    Box2D leftBox = new Box2D(left, midX, bottom, top);
    Box2D rightBox = new Box2D(midX, right, bottom, top);

    return new Pair<>(leftBox, rightBox);
}

