    if (newSize > MAX_VECTOR_SIZE) {
        newSize = MAX_VECTOR_SIZE;
    }
    if (newSize <= currentSize) {
        return;
    }
    byte[] newArray = new byte[newSize];
    System.arraycopy(data, 0, newArray, 0, currentSize);
    data = newArray;
    currentSize = newSize;
    capacity = newSize;
}

