public static String capitalize(String name) {
    if (name == null || name.isEmpty()) {
        return name;
    }
    // If the first two characters are both uppercase, return the name as is (e.g. "URL")
    if (name.length() >= 2 && Character.isUpperCase(name.charAt(0)) && Character.isUpperCase(name.charAt(1))) {
        return name;
    }
    // Capitalize the first character and ensure the rest are unchanged (handle mixed case)
    if (Character.isUpperCase(name.charAt(0))) {
        return name;
    }
    return Character.toUpperCase(name.charAt(0)) + name.substring(1);
}

public static String capitalize(String name) {
    if (name == null) {
        return null;
    }
    if (name.length() == 0) {
        return name;
    }
    char firstChar = name.charAt(0);
    char secondChar = name.length() > 1 ? name.charAt(1) : 0;

    if (Character.isUpperCase(firstChar)) {
        if (Character.isUpperCase(secondChar)) {
            return name;
        } else {
            return name.substring(0, 1).toLowerCase() + name.substring(1);
        }
    } else {
        return name;
    }
}

