public static String capitalize(String name) {
    if (name == null || name.isEmpty()) {
        return name;
    }
    char firstChar = name.charAt(0);
    if (Character.isLowerCase(firstChar)) {
        // Check if the next character is lowercase to avoid capitalizing acronyms like "URL"
        if (name.length() > 1 && Character.isLowerCase(name.charAt(1))) {
            return Character.toUpperCase(firstChar) + name.substring(1);
        } else {
            // If the next character is uppercase (e.g. "URL"), the whole word is likely an acronym, 
            // but standard capitalization strategies usually just capitalize the first letter.
            // However, Introspector.decapitalize's reverse typically just means uppercasing the first letter.
            // Let's stick to the simplest definition of capitalize: uppercase the first letter.
            return Character.toUpperCase(firstChar) + name.substring(1);
        }
    }
    return name;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (out == null || node == null) {
        throw new IllegalArgumentException("DataOutput and LinkedBuffer cannot be null");
    }

    int totalSize = 0;
    Link link = node.head();
    while (link != null) {
        byte[] content = link.content();
        int length = link.length();
        out.write(content, 0, length);
        totalSize += length;
        link = link.next();
    }
    return totalSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
        int totalSize = 0;
        LinkedBuffer current = node;
        while (current != null) {
            totalSize += current.size();
            out.write(current.bytes(), 0, current.size());
            current = current.next();
        }
        return totalSize;
    }

