public String readString() throws IOException {
    int firstByte = read();
    if (firstByte == -1) {
        throw new EOFException();
    }
    long length = UnsignedLong.parseBitLength(firstByte);
    if (length > 0 && (firstByte & (1 << 6)) != 0) {
        length |= read() & 0xFFL;
    }
    if (length > Integer.MAX_VALUE) {
        throw new IOException("String length too large: " + length);
    }
    byte[] buffer = new byte[(int) length];
    for (int i = 0; i < length; ) {
        int readLength = Math.min((int) length - i, 8);
        int bytesRead = read(buffer, i, readLength);
        if (bytesRead == -1) throw new EOFException("Unexpected end of stream in string");
        i += bytesRead;
    }
    return new String(buffer, StandardCharsets.UTF_8);
}

