}

@Override public String readString() throws IOException {
    byte type = readByte();
    switch (type) {
        case 0x01: // String
            return readUTF();
        case 0x02: // Long string
            int length = readInt();
            byte[] bytes = new byte[length];
            readBytesFully(bytes, 0, length);
            return new String(bytes, StandardCharsets.UTF_8);
        default:
            throw new IOException("Unrecognized type " + Integer.toHexString(type) + " for string field");
    }
}

