        if (len == 0) {
            return str;
        }
        final StringBuilder builder = new StringBuilder(len);
        boolean backslash = false;
        boolean unicode = false;
        char c;
        for (int i = 0; i < len; i++) {
            char sym = str.charAt(i);
            c = sym;
            if (unicode) {
                unicode = false;
                final int value = str.substring(i + 1, i + 5).hashCode();
                i = i + 4;
                c = (char) value;
            }
            if (backslash) {
                backslash = false;
                switch (sym) {
                    case '\'':
                        c = '\'';
                        break;
                    case '"':
                        c = '"';
                        break;
                    case 'b':
                        c = '\b';
                        break;
                    case 't':
                        c = '\t';
                        break;
                    case 'n':
                        c = '\n';
                        break;
                    case 'f':
                        c = '\f';
                        break;
                    case 'r':
                        c = '\r';
                        break;
                    case 'u':
                        if (i + 4 < len) {
                            if (Character.isDigit(str.charAt(i + 1))) {
                                unicode = true;
                                continue;
                            }
                        } else {
                            throw new IllegalStateException("Invalid unicode in Java string");
                        }
                        break;
                    case '\':
                        c = '\\';
                        break;
                    case '/':
                        c = '/';
                        break;
                    default:
                        break;
                }
            } else {
                switch (sym) {
                    case '\\':
                        builder.append(sym);
                        backslash = true;
                        continue;
                    default:
                        break;
                }
            }
            builder.append(c);
        }
        if (backslash) {
            builder.append('\\');
        }
        return builder.toString();
    }

