public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    int len = str.length();
    if (len == 0) {
        return str;
    }
    StringBuilder buf = new StringBuilder(len);
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= len) {
                buf.append(c);
                continue;
            }
            i++;
            char next = str.charAt(i);
            switch (next) {
                case 'n':
                    buf.append('\n');
                    break;
                case 't':
                    buf.append('\t');
                    break;
                case 'r':
                    buf.append('\r');
                    break;
                case 'b':
                    buf.append('\b');
                    break;
                case 'f':
                    buf.append('\f');
                    break;
                case '\\':
                    buf.append('\\');
                    break;
                case '\'':
                    buf.append('\'');
                    break;
                case '"':
                    buf.append('"');
                    break;
                case 'u':
                    long unicode = 0;
                    if (i + 4 < len) {
                        for (int j = 0; j < 4; j++) {
                            i++;
                            char hexChar = str.charAt(i);
                            int value = Character.digit(hexChar, 16);
                            if (value == -1) {
                                throw new IllegalArgumentException("Invalid unicode escape sequence: " + str.substring(i - 4, i));
                            }
                            unicode = (unicode << 4) | value;
                        }
                        buf.append((char) unicode);
                    } else {
                        buf.append('\\');
                        buf.append('u');
                    }
                    break;
                default:
                    buf.append('\\');
                    buf.append(next);
                    break;
            }
        } else {
            buf.append(c);
        }
    }
    return buf.toString();
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    int len = str.length();
    if (len == 0) {
        return str;
    }
    final StringBuilder buf = new StringBuilder(len);
    for (int i = 0; i < len; i++) {
        final char ch = str.charAt(i);
        if (ch != '\\') {
            buf.append(ch);
        } else if (i < len - 1) {
            final char nextCh = str.charAt(i + 1);
            switch (nextCh) {
                case 'b':
                    buf.append('\b');
                    i++;
                    break;
                case 't':
                    buf.append('\t');
                    i++;
                    break;
                case 'n':
                    buf.append('\n');
                    i++;
                    break;
                case 'f':
                    buf.append('\f');
                    i++;
                    break;
                case 'r':
                    buf.append('\r');
                    i++;
                    break;
                case 'u':
                    if (i + 5 < len) {
                        final String s = str.substring(i + 2, i + 6);
                        final char code = (char)Integer.parseInt(s, 16);
                        buf.append(code);
                        i += 5;
                    } else {
                        throw new IllegalArgumentException("Invalid Unicode escape: \"" + str.substring(i) + "\"");
                    }
                    break;
                case '"':
                case '\'':
                case '\\':
                    i++;
                    buf.append(nextCh);
                    break;
                default:
                    buf.append(ch);
                    break;
            }
        }
    }
    return buf.toString();
}

