private int computeBinaryLog(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer");
    }
    int bitLength = 0;
    while (n > 0) {
        bitLength++;
        n >>= 1;
    }
    return bitLength;
}

private int computeBinaryLog(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    if (n == 1) {
        return 1;
    }
    int result = 0;
    while (n > 1) {
        n >>= 1;
        result++;
    }
    return result + 1;
}

private int computeBinaryLog(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    int result = 0;
    int current = 1;
    while (current < n) {
        current <<= 1;
        result++;
    }
    return result + 1;
}

private int computeBinaryLog(int n) {
    return n > 0 ? 32 - Integer.numberOfLeadingZeros(n) : 0;
}

private int computeBinaryLog(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer");
    }
    // Find the position of the highest set bit, which is floor(log2(n)) + 1
    // For n=1, returns 1; for n=2, returns 2; for n=3, returns 2; etc.
    int count = 0;
    int temp = n;
    while (temp > 0) {
        count++;
        temp >>= 1;
    }
    return count;
}

