    }

    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    Node current = circ.node();

    while (current == start) {
        if (predicate.test(current) && current != stop) {
            return circ;
        }
        circ.advance();
        current = circ.node();
        if (current == stop) {
            break;
        }
    }

    // If we didn't break in the loop (e.g., if start == stop was handled above but let's be safe)
