@Override public Action inspect(AtmosphereResource r){
        if (r.transport() == AtmosphereResource.TRANSPORT.POLLY) {
            r.suspend(this.suspendTimeout, TimeUnit.SECONDS);
        }
        if (this.keepAlive) {
            r.action(AtmosphereFramework.SUSPEND);
        } else {
            r.cancel();
        }
        return Action.CONTINUE;
    }

@Override
public Action inspect(AtmosphereResource r) {
    if (r == null) {
        return Action.ABORT;
    }

    try {
        if (r.transport() == io.atmosphere.config_TRANSPORT.SSE) {
            r.suspend();
        }
    } catch (Exception e) {
        // Handle exception appropriately, e.g., log or rethrow
        return Action.ABORT;
    }

    return Action.CONTINUE;
}

public Action inspect(AtmosphereResource r) {
    try {
        if (r == null) {
            return Action.CONTINUE;
        } else {
            if (r.transport() == AtmosphereResource.TRANSPORT.LONG_POLLING) {
                r.suspend();
            } else if (r.transport() == AtmosphereResource.TRANSPORT.WEBSOCKET) {
                r.suspend();
            }
            return Action.CONTINUE;
        }
    } catch (Exception e) {
        // Log and return CONTINUE to handle gracefully
        return Action.CONTINUE;
    }
}

@Override
public Action inspect(AtmosphereResource r) {
    if (r == null) {
        return Action.CONTINUE;
    }

    AtmosphereResource.TRANSPORT transportType = r.transport();

    if (transportType == AtmosphereResource.TRANSPORT.COMET) {
        r.suspend();
    } else if (transportType == AtmosphereResource.TRANSPORT.LONG_POLLING) {
        r.action(AtmosphereActionAction.CONTINUE);
    }

    return Action.CONTINUE;
}

@Override public Action inspect(AtmosphereResource r){
    if (r == null) return Action.CONTINUE;
    String transport = r.transport();
    if (transport != null) {
        if (AtmosphereResource.TRANSPORT.SSE.value().equalsIgnoreCase(transport) || AtmosphereResource.TRANSPORT.LONG_POLLING.value().equalsIgnoreCase(transport)) {
            r.suspend();
        }
    }
    return Action.CONTINUE;
}

public double vertexWeight(Set<V> v) {
    double sum = 0.0;
    for (V neighbor : v) {
        sum += weight(neighbor);
    }
    return sum;
}

public double vertexWeight(Set<V> v) {
    double sum = 0.0;
    if (v == null) {
        return sum;
    }
    for (V vertex : v) {
        if (vertex == null) {
            continue;
        }
        for (V other : v) {
            if (other == null || other.equals(vertex)) {
                continue;
            }
            sum += edgeWeight(other, vertex);
        }
    }
    return sum;
}

public double vertexWeight(Set<V> v) {
    double sum = 0.0;
    if (v == null || graph == null) {
        return 0.0;
    }
    for (V vertex : v) {
        Set<V> predecessors = graph.incomingNeighbors(vertex);
        for (V pred : predecessors) {
            double weight = graph.getEdgeWeight(pred, vertex);
            if (weight != 0.0) {
                sum += weight;
            }
        }
    }
    return sum;
}

