public int compare(Object aObj1, Object aObj2) {
    if (aObj1 == null && aObj2 == null) {
        return 0;
    } else if (aObj1 == null) {
        return -1;
    } else if (aObj2 == null) {
        return 1;
    } else if (aObj1 instanceof Comparable && aObj2 instanceof Comparable) {
        try {
            @SuppressWarnings("unchecked")
            Comparable<Object> obj1 = (Comparable<Object>) aObj1;
            if (obj1.getClass().equals(aObj2.getClass())) {
                return obj1.compareTo(aObj2);
            } else {
                return aObj1.getClass().getName().compareTo(aObj2.getClass().getName());
            }
        } catch (ClassCastException e) {
            return aObj1.getClass().getName().compareTo(aObj2.getClass().getName());
        }
    } else {
        return aObj1.toString().compareTo(aObj2.toString());
    }
}

