        a = a.next;
    }
    return appended;
}

public int appendLoopOnAppenders(LoggingEvent event) {
    int count = 0;
    Appender[] appenders = this.callbacks;
    if (appenders == null) {
        return count;
    }
    for (int i = 0; i < appenders.length; i++) {
        if (appenders[i] == null) {
            continue;
        }
        try {
            appenders[i].doAppend(event);
            count++;
        } catch (Exception e) {
            // Ignore exceptions from individual appenders to continue processing the rest
        }
    }
    return count;
}

public int appendLoopOnAppenders(LoggingEvent event) {
    int total = 0;
    AppenderIterator iterator = ((AppenderSkeleton) this).getAllAppenders();
    try {
        while (iterator.hasNext()) {
            Appender appender = iterator.next();
            appender.doAppend(event);
            total++;
        }
    } finally {
        if (iterator != null) {
            iterator.close();
        }
    }
    return total;
}

