protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || tour.isEmpty()) {
        return null;
    }

    int n = tour.size();
    if (n == 0) {
        return null;
    }

    Map<V, Set<E>> adjacencyMap = new HashMap<>();
    for (V vertex : graph.getVertices()) {
        adjacencyMap.put(vertex, graph.getEdges(vertex));
    }

    V startVertex = null;
    for (E edge : tour) {
        Set<V> endpoints = graph.getEndpoints(edge);
        if (endpoints != null && !endpoints.isEmpty()) {
            startVertex = endpoints.iterator().next();
            break;
        }
    }

    if (startVertex == null) {
        return null;
    }

    List<V> path = new ArrayList<>();
