int addConstantNameAndType(final String name, final String descriptor) {
        int nameIndex = addConstantUtf8(name);
        int descriptorIndex = addConstantUtf8(descriptor);
        if (nameIndex == -1 || descriptorIndex == -1) {
            return -1;
        }

        int key = CONSTANT_NAMEANDTYPE_TAG + (nameIndex << 16) | descriptorIndex;
        if (constantPool.containsKey(key)) {
            return constantPool.getIntValue(key);
        }

        int index = addConstant(CONSTANT_NAMEANDTYPE_TAG, nameIndex, descriptorIndex);
        return index;
    }

int addConstantNameAndType(final String name, final String descriptor) {
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("Name and descriptor cannot be null");
    }

    for (Symbol sym : constantPool) {
        if (sym.getKind() == CONSTANT_NameAndType
                && name.equals(sym.getName())
                && descriptor.equals(sym.getDescriptor())) {
            return sym.getId();
        }
    }

    Symbol symbol = new Symbol(name, descriptor);
    symbol.setKind(CONSTANT_NameAndType);
    constantPool.add(symbol);
    return symbol.getId();
}

int addConstantNameAndType(final String name, final String descriptor) {
    ConstantNameAndType cnat = new ConstantNameAndType(name, descriptor);
    Symbol s = symbols.get(cnat);
    if (s != null) {
        return s.tag;
    }

    String str = name + ":" + descriptor;
    int strIndex = addConstantUTF8(str);
    ConstantURef uRef = new ConstantURef(strIndex);
    int uRefIndex = addConstantUnicodeRef(uRef);

    cnat = new ConstantNameAndType(name, descriptor);
    ConstantNameTag symbol = new ConstantNameTag(cnat, name, descriptor);
    symbols.put(cnat, symbol);
    return symbol.tag;
}

private String unescapeId(String input) {
    if (input == null || input.isEmpty()) {
        return input;
    }
    StringBuilder result = new StringBuilder();
    int i = 0;
    while (i < input.length()) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < input.length()) {
            char next = input.charAt(i + 1);
            // Check if it's a valid escape sequence
            switch (next) {
                case 'n':
                    result.append('\n');
                    i += 2;
                    break;
                case 't':
                    result.append('\t');
                    i += 2;
                    break;
                case '\\':
                    result.append('\\');
                    i += 2;
                    break;
                case 'q':
                    result.append('\'');
                    i += 2;
                    break;
                case 'u':
                    if (i + 5 < input.length() + 1) {
                        try {
                            String hex = input.substring(i + 2, i + 6);
                            int codePoint = Integer.parseInt(hex, 16);
                            result.append((char) codePoint);
                            i += 6;
                        } catch (Exception e) {
                            result.append(c);
                            i++;
                        }
                    } else {
                        result.append(c);
                        i++;
                    }
                    break;
                default:
                    // For other escape sequences, just append the character after backslash
                    result.append(next);
                    i += 2;
                    break;
            }
        } else {
            result.append(c);
            i++;
        }
    }
    return result.toString();
}

