public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null) {
        throw new IllegalArgumentException("Table must not be null");
    }
    if (pane == null) {
        throw new IllegalArgumentException("Scroll pane must not be null");
    }
    int rowCount = table.getRowCount();
    if (row < 0 || row >= rowCount) {
        throw new IllegalArgumentException("Row index is out of bounds: " + row + " (valid range: 0 to " + (rowCount - 1) + ")");
    }
    table.setRowSelectionInterval(row, row);
    table.scrollRectToVisible(table.getCellRect(row, 0, true));
    SwingUtilities.invokeLater(new Runnable() {
        public void run() {
            table.repaint();
        }
    });
}

public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (row < 0 || row >= table.getRowCount() || table == null || pane == null) {
        throw new IllegalArgumentException("Invalid row or component parameters");
    }

    table.clearSelection();
    table.setRowSelectionInterval(row, row);
    pane.ensureRowIsVisible(row);

    // Delay the repaint to ensure the table has time to render the new selection
    SwingUtilities.invokeLater(new Runnable() {
        @Override
        public void run() {
            table.repaint(table.getCellRect(row, 0, false));
        }
    });
}

public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        throw new IllegalArgumentException("Table and JScrollPane must not be null");
    }
    if (row < 0) {
        return;
    }
    // Ensure that the row is valid
    if (row >= table.getRowCount()) {
        // If the row is out of bounds, select the last available row
        row = table.getRowCount() - 1;
        if (row < 0) {
            return;
        }
    }

    // Select the specified row
    table.setRowSelectionInterval(row, row);

    // Access the view-port of the scroll pane
    JViewport viewport = pane.getViewport();

    // Check if the view-port is visible
    if (viewport != null && viewport.isVisible()) {
        // Scroll the table to make the selected row visible
        pane.ensureVisibleIcon(row);

        // Delay the repaint to ensure the table has time to paint the selected row properly
        javax.swing.SwingUtilities.invokeLater(new Runnable() {
            @Override
            public void run() {
                table.repaint();
            }
        });
    }
}

public static void selectRow(int row, JTable table, JScrollPane pane) {
    int height = pane.getViewport().getExtent().height;
    int currentScrollLocation = pane.getVerticalScrollBar().getValue();
    int rowHeight = table.getRowHeight();
    int tableHeight = rowHeight * table.getRowCount();
    if (tableHeight > height) {
        int preferredScroll = row * rowHeight - (height - rowHeight) / 2;
        preferredScroll = Math.max(preferredScroll, 0);
        preferredScroll = Math.min(preferredScroll, (tableHeight - height));
        pane.ensureVisible(row);
        pane.getVerticalScrollBar().setValue(preferredScroll);
    }
    table.setRowSelectionInterval(row, row);
    SwingUtilities.invokeLater(table::repaint);
    SwingUtilities.invokeLater(pane::repaint);
}

public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        return;
    }

    table.setRowSelectionInterval(row, row);
    pane.getViewport().setViewPosition(new Point(0, table.getExtentSize().height * row));
    pane.repaint();

    new SwingTimer().delay(100, new Timer(100, e -> {
        pane.repaint();
    })::start);
}

