    ensureCapacity(4);
    byte[] data = this.data;
    int length = this.length;
    // We assume the data is stored as Little Endian, as is typical for JVM bytecode.
    // The caller is responsible for ensuring 'intValue' represents a valid Java int.
    data[length++] = (byte) (intValue & 0xFF);
    data[length++] = (byte) ((intValue >> 8) & 0xFF);
    data[length++] = (byte) ((intValue >> 16) & 0xFF);
    data[length++] = (byte) (intValue >> 24);
    this.length = length;
    return this;
