        // Check for edge cases: 0 or 1 vertices are trivially cliques
        if(vertices.isEmpty() || vertices.size() == 1){
            return true;
        }

        // A complete graph with n vertices must have n(n-1)/2 edges
        int n = vertices.size();
        int expectedEdgeCount = n * (n - 1) / 2;

        // Check if the number of edges in the induced subgraph matches the expected count
        int actualEdgeCount = 0;
        for(V v : vertices){
            actualEdgeCount += graph.getDegree(v);
        }
        actualEdgeCount /= 2; // Each edge is counted twice (once for each endpoint)

        return actualEdgeCount == expectedEdgeCount;
    }

